SELECT j.id, j.title, j.category, j.city, j.education, j.salary_min AS salaryMin, j.salary_max AS salaryMax, j.created_at AS createdAt, c.id AS companyId, c.name AS companyName, dcat.label AS categoryLabel, dcity.label AS cityLabel, dedu.label AS educationLabel, dind.label AS companyIndustryLabel, (CASE WHEN j.category = #{expectCategory} THEN 3 ELSE 0 END + CASE WHEN j.city = #{expectCity} THEN 2 ELSE 0 END + CASE WHEN j.salary_min <= #{expectSalaryMax} OR j.salary_max >= #{expectSalaryMin} THEN 1 ELSE 0 END) AS matchScore FROM jobs j JOIN companies c ON j.company_id = c.id LEFT JOIN dict_items dcat ON j.category = dcat.code AND dcat.dict_type = 'category' LEFT JOIN dict_items dcity ON j.city = dcity.code AND dcity.dict_type = 'city' LEFT JOIN dict_items dedu ON j.education = dedu.code AND dedu.dict_type = 'education' LEFT JOIN dict_items dind ON c.industry = dind.code AND dind.dict_type = 'industry'
j.status = 'ACTIVE' AND c.status = 'APPROVED' AND j.category = #{category} AND j.city = #{city} AND (j.title LIKE CONCAT('%', #{kw}, '%') OR j.description LIKE CONCAT('%', #{kw}, '%'))
ORDER BY matchScore DESC, j.created_at DESC LIMIT #{offset}, #{size}
